import random, itertools, math, time

def wins(A,B):
    return sum(1 for a in A for b in B if a>b)

def ok(dice):
    return [wins(dice[i], dice[(i+1)%5]) for i in range(5)]

# random search dice as sorted lists of 6 in 0..11
best=None
start=time.time()
for t in range(200000):
    dice=[sorted(random.choices(range(12), k=6)) for _ in range(5)]
    scores=ok(dice)
    if min(scores)>18:
        print('found', dice, scores, 'iter', t)
        break
    m=sum(max(0,19-s) for s in scores)
    if best is None or m<best[0]:
        best=(m,dice,scores)
        # print('best',best)
else:
    print('not found best', best)
print('time',time.time()-start)

